from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def root(my_header: str = Header(None, convert_underscores=True)):
    return {"my_header": my_header}

@app.get("/false")
async def root_false(my_header: str = Header(None, convert_underscores=False)):
    return {"my_header": my_header}

client = TestClient(app)

def test_convert_underscores_true():
    # Should accept hyphenated
    res = client.get("/", headers={"my-header": "foo"})
    print(f"True - hyphenated: {res.json()}")
    assert res.json() == {"my_header": "foo"}

    # Should NOT accept underscored (this is what we want to fix)
    res = client.get("/", headers={"my_header": "bar"})
    print(f"True - underscored: {res.json()}")
    # Currently this probably returns {"my_header": "bar"}
    # We want it to return {"my_header": None}

def test_convert_underscores_false():
    # Should accept underscored
    res = client.get("/false", headers={"my_header": "baz"})
    print(f"False - underscored: {res.json()}")
    assert res.json() == {"my_header": "baz"}

if __name__ == "__main__":
    test_convert_underscores_true()
    test_convert_underscores_false()

